using LuminosHrm.Models;
namespace LuminosHrm.Services;
public class EmployeeService : IEmployeeService {
 private readonly List<Employee> employees = new(); private readonly List<AttendanceRecord> attendance = new();
 private readonly string[] first={"Olivia","Maya","Ethan","Noah","Amara","Liam","Sofia","Daniel","Zoe","James","Nia","Leo","Ava"};
 public EmployeeService(){ var roles=new[]{("VP Engineering","Engineering"),("Product Manager","Product"),("Senior Designer","Design"),("Growth Lead","Marketing"),("People Partner","HR"),("Finance Analyst","Finance"),("Operations Lead","Operations"),("Backend Engineer","Engineering"),("UX Researcher","Design"),("Account Executive","Marketing"),("QA Engineer","Engineering"),("Data Analyst","Finance"),("Office Manager","Operations")}; for(int i=0;i<13;i++){var name=$"{first[i]} {new[]{"Chen","Patel","Morgan","Williams","Okafor","Rivera","Khan","Brooks","Evans","Kim","Santos","Miller","Adams"}[i]}"; var e=new Employee{Id=i+1,FullName=name,Email=$"{first[i].ToLower()}.{name.Split(' ')[1].ToLower()}@luminos.co",Phone=$"07912345{i:00}",Role=roles[i].Item1,Dept=roles[i].Item2,Salary=65000+i*4200,StartDate=DateTime.Today.AddDays(-30-i*41),Avatar=$"https://i.pravatar.cc/96?img={i+12}"}; employees.Add(e); attendance.Add(new AttendanceRecord{EmployeeId=e.Id,Date=DateTime.Today,Status=i==5?"Late":i==8?"Remote":"Present"}); }}
 public IReadOnlyList<Employee> GetAll()=>employees; public Employee? Get(int id)=>employees.FirstOrDefault(e=>e.Id==id); public Employee Add(Employee e){e.Id=employees.Max(x=>x.Id)+1;employees.Insert(0,e);attendance.Add(new AttendanceRecord{EmployeeId=e.Id,Date=DateTime.Today});return e;} public void Update(Employee e){var old=Get(e.Id);if(old is null)return; employees[employees.IndexOf(old)]=e;} public IReadOnlyList<AttendanceRecord> GetAttendance(DateTime date){return employees.Select(e=>attendance.FirstOrDefault(r=>r.EmployeeId==e.Id&&r.Date.Date==date.Date)??new AttendanceRecord{EmployeeId=e.Id,Date=date}).ToList();} public void UpdateAttendance(AttendanceRecord r){var old=attendance.FirstOrDefault(x=>x.EmployeeId==r.EmployeeId&&x.Date.Date==r.Date.Date);if(old is null)attendance.Add(r);else{old.Status=r.Status;old.CheckIn=r.CheckIn;old.CheckOut=r.CheckOut;old.HoursWorked=r.HoursWorked;}} }
